Given a Singly Linked List, the task is to find the Length of the Linked List.Examples:Input: LinkedList = 1->3->1->2->1Output: 5Explanation: The linked list has 5 nodes.Input: LinkedList = 2->4->1->9->5->3->6Output: 7 Explanation: The linked list has 7 nodes.Input: LinkedList = 10->20->30->40->50->60Output: 6Explanation: The linked list has 6 nodes.Try It YourselfIterative Approach to Find the Length of a Linked ListThe idea is similar to traversal of Linked List with an additional variable to count the number of nodes in the Linked List. Steps to find the length of the Linked List:Initialize count as 0. Initialize a node pointer, curr = head.Do following while curr is not NULLcurr = curr -> nextIncrement count by 1.Return count.
            C++

    // Iterative C++ program to find length
// or count of nodes in a linked list

#include <bits/stdc++.h>
using namespace std;

// Link list node
class Node {
public:
    int data;
    Node* next;

    // Constructor to initialize a new node with data
    Node(int new_data) {
        data = new_data;
        next = nullptr;
    }
};

// Counts number of nodes in linked list
int countNodes(Node* head) {

    // Initialize count with 0
    int count = 0;

    // Initialize curr with head of Linked List
    Node* curr = head;

    // Traverse till we reach nullptr
    while (curr != nullptr) {

      	// Increment count by 1
        count++;

      	// Move pointer to next node
        curr = curr->next;
    }

  	// Return the count of nodes
    return count;
}

// Driver code
int main() {

    // Create a hard-coded linked list:
    // 1 -> 3 -> 1 -> 2 -> 1
    Node* head = new Node(1);
    head->next = new Node(3);
    head->next->next = new Node(1);
    head->next->next->next = new Node(2);
    head->next->next->next->next = new Node(1);

    // Function call to count the number of nodes
    cout << "Count of nodes is " << countNodes(head);
    return 0;
}


